using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct ShopId : IEquatable<ShopId>, IComparable<ShopId>
    {
        public Guid Value { get; }

        public ShopId(Guid value)
        {
            Value = value;
        }

        public static ShopId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static ShopId NewRandom() => new ShopId(Guid.NewGuid());

        public static ShopId Parse(string text) => new ShopId(Guid.Parse(text));

        public static bool TryParse(string text, out ShopId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new ShopId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(ShopId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is ShopId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(ShopId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(ShopId left, ShopId right) => left.Equals(right);

        public static bool operator !=(ShopId left, ShopId right) => !left.Equals(right);
    }
}
